package net.officefloor.hq.app.person;

import java.util.List;

/** Body of a bulk grade: the ids of the selected people, in any order, the grade they are given and
 *  the date it applies from (blank: the sheet's today). */
public record BulkGradeRequest(List<Long> personIds, String grade, String from) {
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.List;
import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Refuses a bulk grade with no one selected, a grade not A, B or C, or a from-date not a date. */
public class ValidateBulkGrade {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    public void validate(@RequestBody BulkGradeRequest request, Out<BulkGradeRequest> body)
            throws InvalidPersonException {
        List<Long> ids = request == null || request.personIds() == null ? List.of()
                : request.personIds().stream().filter((id) -> id != null).toList();
        if (ids.isEmpty()) {
            throw new InvalidPersonException("Select the people to grade");
        }
        String grade = request.grade() == null ? "" : request.grade().trim();
        if (!GRADES.contains(grade)) {
            throw new InvalidPersonException("Grade must be A, B or C");
        }
        String from = request.from() == null ? "" : request.from().trim();
        if (!from.isEmpty()) {
            try {
                LocalDate.parse(from);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("Not a date: " + from);
            }
        }
        body.set(new BulkGradeRequest(ids, grade, from.isEmpty() ? null : from));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.HashSet;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetArchivedException;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** Gives the selected people the grade in list order (by their places in the list), each as the
 *  person form would (see {@link ApplyPerson}: from the from-date, blank the sheet's today) and
 *  recorded as it would record it (its PERSON_EDITED line, then the rollup lines it moved). A
 *  selected id not on the sheet is skipped. A viewer may grade no one: none are given it. Refused on an
 *  archived sheet. */
public class BulkGradePeople {
    public void grade(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "by", required = false) String by, @Val BulkGradeRequest request,
            PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, SettingRepository settings, RoleRepository roles, Audit audit, Out<BulkGradeResult> result)
            throws PersonConflictException, SheetArchivedException {
        String id = sheetId.trim();
        String user = by == null ? "" : by;
        if (sheets.isArchived(id)) {
            throw new SheetArchivedException("The sheet is archived");
        }
        if (Role.VIEWER.equals(roles.roleOf(id, user))) {
            result.set(new BulkGradeResult(0));
            return;
        }
        Set<Long> selected = new HashSet<>(request.personIds());
        LocalDate today = sheets.today(id);
        int graded = 0;
        Rollup before = Rollup.of(id, people, claims, rates, sheets, settings);
        for (Person listed : people.list(id)) {
            if (!selected.contains(listed.getId())) continue;
            Person person = people.find(id, listed.getId());
            // As the form: no from-date and the grade already in force gives none.
            if (request.from() != null || !request.grade().equals(person.getGrade())) {
                person.giveGrade(request.grade(), request.from() != null ? request.from() : today.toString(), today);
            }
            if (!people.update(person)) {
                throw new PersonConflictException(person.getId());
            }
            if (person.getRecorded() != null) {
                people.saveGrade(person, person.getRecorded(), user);
            }
            graded++;
            audit.record("PERSON_EDITED sheet=" + id + " by=" + user + " name=" + person.getName()
                    + " grade=" + person.getGrade());
            Rollup after = Rollup.of(id, people, claims, rates, sheets, settings);
            for (String line : after.changesSince(before, id, user)) {
                audit.record(line);
            }
            before = after;
        }
        result.set(new BulkGradeResult(graded));
    }
}
package net.officefloor.hq.app.person;

/** How many of the selected people were given the grade. */
public record BulkGradeResult(int graded) {
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithBulkGrade {
    public void respond(@Val BulkGradeResult result, ObjectResponse<BulkGradeResult> response) {
        response.send(result);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Retires the person from the date asked (the sheet's today when none): they count as retired at once. */
public class RetirePerson {
    public void retire(@Val RetireRequest request, @Val Person person, SheetRepository sheets,
            PersonRepository people) {
        person.setRetiredFrom(request.from() != null ? request.from()
                : sheets.today(person.getSheetId()).toString());
        people.updateRetired(person);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Last write step: only a retirement that went through is recorded. */
public class RecordPersonRetired {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Person person, Audit audit) {
        audit.record("PERSON_RETIRED sheet=" + person.getSheetId() + " by=" + (by == null ? "" : by)
                + " name=" + person.getName() + " from=" + person.getRetiredFrom());
    }
}
